func PathEscape(pth string) string {
	// url.Parse treats '#' and '?' as fragment and query separators,
	// but when escaping a path they are just regular characters.
	pth = strings.ReplaceAll(pth, "#", "%23")
	pth = strings.ReplaceAll(pth, "?", "%3F")
	u, err := url.Parse(pth)
	if err != nil {
		panic(err)
	}
	return u.EscapedPath()
}

